CREATE TABLE IF NOT EXISTS app_users (id BIGSERIAL PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, role VARCHAR(50) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS transactions (id BIGSERIAL PRIMARY KEY, transaction_date DATE NOT NULL, account VARCHAR(150) NOT NULL, category VARCHAR(100) NOT NULL, type VARCHAR(30) NOT NULL, amount NUMERIC(15,2) NOT NULL, department VARCHAR(100), description VARCHAR(500), source_system VARCHAR(100), flagged BOOLEAN NOT NULL DEFAULT FALSE, anomaly_reason VARCHAR(500), anomaly_score DOUBLE PRECISION, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_tx_date ON transactions(transaction_date); CREATE INDEX IF NOT EXISTS idx_tx_category ON transactions(category);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, username VARCHAR(100) NOT NULL, action VARCHAR(50) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id VARCHAR(100), details VARCHAR(2000), timestamp TIMESTAMP WITH TIME ZONE NOT NULL);
